import { FormEvent, useEffect, useMemo, useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { ColumnDef, flexRender, getCoreRowModel, useReactTable } from '@tanstack/react-table'
import { Archive, ArrowUpRight, BarChart3, Bot, Check, ChevronDown, ChevronRight, CircleAlert, CircleCheck, Database, FileSearch, FileSpreadsheet, FolderKanban, FolderUp, GitCompareArrows, Home, Info, Layers3, LoaderCircle, Menu, PackageSearch, Pencil, Plus, RefreshCw, Search, Settings, ShieldCheck, SlidersHorizontal, TriangleAlert, UploadCloud, X } from 'lucide-react'
import { Backup, Benchmark, bootstrap, CostItem, formatAmount, ImportIssue, ImportJob, ImportParsePreview, isStaticDemo, LibraryKey, LibrarySummary, MetricTemplate, Project, ProjectDetail, QualityReport, request, Rule, SearchResult, UnitConversion, WorkspaceRecord, WorkspaceSearchResult } from './api'
import { Select } from './components/Select'
import { Input } from './components/Input'
import { Textarea } from './components/Textarea'

type View = 'overview' | 'projects' | 'imports' | 'explorer' | 'catalog' | 'resource' | 'quota' | 'quality' | 'matching' | 'rules' | 'settings'
const labels: Record<View, string> = { overview: '总览', projects: '项目库', imports: '项目与导入', explorer: '造价数据工作台（跨库总览）', catalog: '清单库', resource: '工料机库', quota: '定额库', quality: '数据质量中心', matching: '清单匹配', rules: '标准化规则', settings: '备份与 AI' }
const nav = [['overview', Home], ['projects', FolderKanban], ['imports', FolderUp], ['explorer', FileSearch], ['catalog', Layers3], ['resource', PackageSearch], ['quota', Database], ['quality', TriangleAlert], ['matching', GitCompareArrows], ['rules', SlidersHorizontal], ['settings', Settings]] as const
const Button = ({ children, className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) => <button className={`button ${className}`} {...props}>{children}</button>
const Status = ({ value }: { value: string }) => <span className={`status status-${value}`}>{({ published: '已发布', review: '待复核', completed: '已完成', analyzing: '结构分析', parsing: '解析中', mapping_review: '待确认映射', running: '解析中', queued: '等待中', draft: '草稿', resolved: '已处理', ignored: '已忽略', open: '待处理', complete: '成功', searchable: '检索可用', benchmark_candidate: '标杆候选', restricted: '参考受限' } as Record<string, string>)[value] || value}</span>
const Empty = ({ text }: { text: string }) => <div className="empty"><Database /><strong>{text}</strong><span>完成首次导入后，这里会显示可核查的数据。</span></div>
const ErrorLine = ({ error }: { error: unknown }) => error ? <div className="error-line">{error instanceof Error ? error.message : '请求失败'}</div> : null
const formatProjectFeature = (value?: string) => {
  if (!value) return '—'
  const formatted = value
    .replace(/^\s*项目特征\s*[:：]\s*/u, '')
    .replace(/\s*工作内容\s*[:：]\s*/gu, '\n工作内容\n')
    .replace(/(?:^|\s)(\d+[.、])\s*/gu, '\n$1 ')
    .replace(/[:：]/gu, '：')
    .replace(/[ \t]+\n/gu, '\n')
    .replace(/\n{2,}/gu, '\n')
    .trim()
  return formatted || '—'
}

export function App() {
  const [view, setView] = useState<View>('overview'); const health = useQuery({ queryKey: ['health'], queryFn: bootstrap }); const [sidebarCollapsed, setSidebarCollapsed] = useState(() => typeof localStorage !== 'undefined' && localStorage.getItem('cost-data-sidebar-collapsed') === 'true'); const [sidebarWidth, setSidebarWidth] = useState(() => { const value = typeof localStorage === 'undefined' ? 218 : Number(localStorage.getItem('cost-data-sidebar-width')); return Number.isFinite(value) && value >= 180 && value <= 320 ? value : 218 }); const [resizingSidebar, setResizingSidebar] = useState(false)
  const toggleSidebar = () => { const next = !sidebarCollapsed; setSidebarCollapsed(next); if (typeof localStorage !== 'undefined') localStorage.setItem('cost-data-sidebar-collapsed', String(next)) }
  useEffect(() => { if (!resizingSidebar) return; const move = (event: PointerEvent) => setSidebarWidth(Math.min(320, Math.max(180, event.clientX))); const stop = () => setResizingSidebar(false); window.addEventListener('pointermove', move); window.addEventListener('pointerup', stop); return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', stop) } }, [resizingSidebar])
  useEffect(() => { if (!resizingSidebar && typeof localStorage !== 'undefined') localStorage.setItem('cost-data-sidebar-width', String(sidebarWidth)) }, [resizingSidebar, sidebarWidth])
  const beginResizeSidebar = () => { setResizingSidebar(true); document.body.style.cursor = 'col-resize'; document.body.style.userSelect = 'none' }
  return <div className={`shell ${sidebarCollapsed ? 'sidebar-collapsed' : ''}`} style={{ gridTemplateColumns: sidebarCollapsed ? '64px minmax(0,1fr)' : `${sidebarWidth}px minmax(0,1fr)` }}><aside><div className="brand"><span className="brand-mark">造</span><div><strong>工程造价数据库</strong><small>历史数据资产库</small></div></div><nav aria-label="主导航">{nav.map(([id, Icon]) => <button key={id} aria-label={labels[id]} className={view === id ? 'active' : ''} onClick={() => setView(id)}><Icon /><span>{labels[id]}</span></button>)}</nav><div className="local-state"><ShieldCheck /><div><strong>{isStaticDemo ? '在线静态预览' : '数据保存在本机'}</strong><small>{isStaticDemo ? '未连接本地数据服务' : health.isSuccess ? '本地服务运行正常' : '正在连接本地服务'}</small></div></div><div className="sidebar-resize-handle" role="separator" aria-label="调整导航栏宽度" onPointerDown={beginResizeSidebar} onDoubleClick={() => setSidebarWidth(218)} /></aside><main><header><div className="header-leading"><button className="sidebar-toggle" aria-label={sidebarCollapsed ? '展开导航栏' : '收起导航栏'} title={sidebarCollapsed ? '展开导航栏' : '收起导航栏'} onClick={toggleSidebar}><Menu /></button><span>工程造价数据库</span><ChevronRight /><strong>{labels[view]}</strong></div></header>{view === 'overview' && <Overview go={setView} />}{view === 'projects' && <Projects />}{view === 'imports' && <Imports />}{view === 'explorer' && <Explorer go={library => setView(library)} />}{(['catalog', 'resource', 'quota'] as const).includes(view as LibraryKey) && <LibraryExplorer key={view} library={view as LibraryKey} ready={health.isSuccess || isStaticDemo} />}{view === 'quality' && <QualityCenter />}{view === 'matching' && <Matching />}{view === 'rules' && <Rules />}{view === 'settings' && <SystemSettings />}</main></div>
}

function Overview({ go }: { go: (v: View) => void }) {
  const stats = useQuery({ queryKey: ['dashboard'], queryFn: () => request<Record<string, number>>('/dashboard') }); const projects = useQuery({ queryKey: ['projects'], queryFn: () => request<Project[]>('/projects') }); const d = stats.data || { projects: 0, published_versions: 0, cost_items: 0, open_issues: 0 }
  const isReady = d.open_issues === 0 && d.published_versions > 0
  return <section className="page overview-page"><div className="overview-heading"><div><div className="eyebrow">WORKSPACE OVERVIEW <span>·</span> {new Date().toLocaleDateString('zh-CN', { month: 'long', day: 'numeric' })}</div><h1>数据工作总览</h1><p>先处理异常，再使用已发布数据进行检索与比较。</p></div><div className="overview-actions"><Button onClick={() => go('explorer')}><FileSearch />检索数据</Button><Button className="primary" onClick={() => go('imports')}><Plus />导入项目</Button></div></div><ErrorLine error={stats.error} /><div className="overview-kpis"><div className="overview-kpi accent"><span>项目总数</span><strong>{d.projects}</strong><small>已纳入数据库的项目</small><FolderKanban /></div><div className="overview-kpi"><span>已发布版本</span><strong>{d.published_versions}</strong><small>可用于正式检索</small><Check /></div><div className="overview-kpi"><span>可检索清单项</span><strong>{d.cost_items.toLocaleString()}</strong><small>跨项目累计记录</small><Layers3 /></div><div className={`overview-kpi ${d.open_issues ? 'warn' : 'good'}`}><span>待处理异常</span><strong>{d.open_issues}</strong><small>{d.open_issues ? '建议优先处理' : '当前数据状态良好'}</small><CircleAlert /></div></div><div className="overview-layout"><div className="overview-main"><div className={`readiness ${isReady ? 'ready' : 'attention'}`}><div className="readiness-icon">{isReady ? <Check /> : <CircleAlert />}</div><div><strong>{isReady ? '数据已准备就绪' : '还有数据需要处理'}</strong><p>{isReady ? '当前已发布数据可以直接用于检索、对比和指标分析。' : '完成异常复核和版本发布后，数据才会进入正式检索库。'}</p></div><Button onClick={() => go(isReady ? 'explorer' : 'quality')}>{isReady ? '开始检索' : '查看异常'}<ArrowUpRight /></Button></div><div className="panel recent-panel"><div className="panel-head"><div><h2>最近项目</h2><p>发布后才进入正式检索库</p></div><button className="text-button" onClick={() => go('projects')}>查看全部 <ArrowUpRight /></button></div>{!projects.data?.length ? <Empty text="尚未导入项目" /> : <div className="table-scroll"><table><thead><tr><th>项目</th><th>地区 / 时间</th><th>专业</th><th>计价体系</th><th>清单项</th><th>版本</th></tr></thead><tbody>{projects.data.map(p => <tr key={p.id} onClick={() => go('projects')}><td><strong>{p.name}</strong><small>{p.result_stage}</small></td><td>{p.region}<small>{p.pricing_date}</small></td><td>{p.specialty}</td><td>{p.pricing_mode}</td><td className="table-number">{p.item_count}</td><td><Status value={p.latest_status || 'draft'} /></td></tr>)}</tbody></table></div>}</div></div><aside className="overview-rail"><div className="rail-head"><span>快捷入口</span><span className="rail-dot" /></div><button className="quick-action" onClick={() => go('imports')}><span className="quick-icon"><FolderUp /></span><span><strong>导入新项目</strong><small>上传 Excel 并开始解析</small></span><ArrowUpRight /></button><button className="quick-action" onClick={() => go('quality')}><span className="quick-icon warning"><CircleAlert /></span><span><strong>数据质量中心</strong><small>{d.open_issues ? `${d.open_issues} 个异常待处理` : '暂无待处理异常'}</small></span><ArrowUpRight /></button><button className="quick-action" onClick={() => go('matching')}><span className="quick-icon"><GitCompareArrows /></span><span><strong>清单匹配</strong><small>查找历史相似清单项</small></span><ArrowUpRight /></button><div className="rail-note"><span className="note-label">数据工作流</span><div className="flow-step done"><i>1</i><span>导入项目</span><Check /></div><div className="flow-line" /><div className={`flow-step ${d.open_issues ? '' : 'done'}`}><i>2</i><span>处理异常</span>{!d.open_issues && <Check />}</div><div className="flow-line" /><div className={`flow-step ${d.published_versions ? 'done' : ''}`}><i>3</i><span>发布并检索</span>{d.published_versions > 0 && <Check />}</div></div></aside></div></section>
}

function Title({ title, text, children }: { title: string; text: string; children?: React.ReactNode }) { return <div className="page-title"><div><h1>{title}</h1><p>{text}</p></div>{children}</div> }

function BenchmarkPanel({ code, project }: { code: string; project: ProjectDetail['project'] }) {
  const benchmark = useQuery({ queryKey: ['benchmark', code, project.project_type, project.specialty], queryFn: () => request<Benchmark>(`/benchmarks/metrics/${code}?project_type=${encodeURIComponent(project.project_type || '')}&specialty=${encodeURIComponent(project.specialty)}`) });
  if (!benchmark.data) return null
  return <div className="benchmark"><span>同类项目标杆 · {benchmark.data.sample_count} 个样本</span><div><b>P25 {formatAmount(benchmark.data.p25)}</b><b>P50 {formatAmount(benchmark.data.p50)}</b><b>P75 {formatAmount(benchmark.data.p75)}</b></div></div>
}

function Projects() {
  const qc = useQueryClient(), [selected, setSelected] = useState<string>(); const projects = useQuery({ queryKey: ['projects'], queryFn: () => request<Project[]>('/projects') }); const detail = useQuery({ queryKey: ['project', selected], queryFn: () => request<ProjectDetail>(`/projects/${selected}`), enabled: !!selected }); const saveProfile = useMutation({ mutationFn: (profile: Record<string, string>) => request(`/projects/${selected}/profile`, { method: 'PATCH', body: JSON.stringify({ profile }) }), onSuccess: () => qc.invalidateQueries({ queryKey: ['projects'] }) });
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const form = new FormData(e.currentTarget); saveProfile.mutate(Object.fromEntries(['structure_form', 'area_basis', 'above_ground_area', 'underground_area', 'floors', 'height', 'decoration_grade', 'foundation_type', 'contract_mode', 'tax_rate'].map(key => [key, String(form.get(key) || '')]))) }
  return <section className="page"><Title title="项目库" text="项目画像决定哪些历史样本可以进入同类项目标杆库。" /><div className="split"><div className="panel"><div className="panel-head"><h2>历史项目</h2></div>{!projects.data?.length ? <Empty text="尚未导入项目" /> : <div className="task-list">{projects.data.map(project => <button key={project.id} className={selected === project.id ? 'selected' : ''} onClick={() => setSelected(project.id)}><div><strong>{project.name}</strong><small>{project.region} · {project.pricing_date} · {project.project_type || '未分类'}</small></div><Status value={project.comparability || 'low'} /><b>{project.item_count}</b><ChevronRight /></button>)}</div>}</div><div className="panel review">{!detail.data ? <Empty text="选择项目以查看数据资产" /> : <><div className="panel-head"><div><h2>{detail.data.project.name}</h2><p>{detail.data.project.region} · {detail.data.project.pricing_date} · {detail.data.project.pricing_mode}</p></div><Status value={detail.data.project.comparability} /></div><div className="asset-counts">{Object.entries(detail.data.data_counts).map(([key, count]) => <div key={key}><span>{({ bill: '清单', quota: '定额', resource: '工料机', measure: '措施费', fee_rate: '费率', metric: '指标' } as Record<string, string>)[key]}</span><strong>{count}</strong></div>)}</div><form className="profile-form" onSubmit={submit}><h3>项目画像</h3><label>结构形式<Input name="structure_form" defaultValue={detail.data.project.profile.structure_form || ''} placeholder="例如：框架剪力墙" /></label><label>面积口径<Input name="area_basis" defaultValue={detail.data.project.profile.area_basis || ''} placeholder="例如：总建筑面积" /></label><label>地上面积<Input name="above_ground_area" defaultValue={detail.data.project.profile.above_ground_area || ''} /></label><label>地下面积<Input name="underground_area" defaultValue={detail.data.project.profile.underground_area || ''} /></label><label>层数<Input name="floors" defaultValue={detail.data.project.profile.floors || ''} /></label><label>装修档次<Input name="decoration_grade" defaultValue={detail.data.project.profile.decoration_grade || ''} /></label><label>基础形式<Input name="foundation_type" defaultValue={detail.data.project.profile.foundation_type || ''} /></label><label>合同模式<Input name="contract_mode" defaultValue={detail.data.project.profile.contract_mode || ''} /></label><label>税率<Input name="tax_rate" defaultValue={detail.data.project.profile.tax_rate || ''} /></label><Button className="primary" disabled={saveProfile.isPending}><Check />保存画像</Button></form><div className="metric-list"><h3>项目指标与标杆</h3>{detail.data.metrics.map(metric => <div key={metric.id}><span>{metric.name}<small>{metric.formula}</small></span><b>{formatAmount(metric.value)} {metric.value.unit}</b><BenchmarkPanel code={metric.code} project={detail.data.project} /></div>)}</div></>}</div></div></section>
}

function QualityCenter() {
  const projects = useQuery({ queryKey: ['projects'], queryFn: () => request<Project[]>('/projects') }); const [version, setVersion] = useState<string>(); const report = useQuery({ queryKey: ['quality', version], queryFn: () => request<QualityReport>(`/quality/projects/${version}`), enabled: !!version });
  return <section className="page"><Title title="数据质量中心" text="异常数据可检索但不进入标杆样本池；阻断错误不可发布。" /><div className="panel"><div className="quality-picker"><label>项目版本<Select value={version || ''} onChange={event => setVersion(event.target.value)}><option value="">选择已发布版本</option>{projects.data?.filter(project => project.latest_version_id).map(project => <option key={project.latest_version_id} value={project.latest_version_id}>{project.name} · V{project.latest_version_no}</option>)}</Select></label></div>{!version ? <Empty text="选择项目版本以生成质量报告" /> : !report.data ? <Empty text="正在计算质量报告" /> : <><div className="quality-stats"><div className="quality-stat good"><span>可发布</span><strong>{report.data.publishable ? '是' : '否'}</strong></div><div className="quality-stat info"><span>待确认</span><strong>{report.data.summary.warnings}</strong></div><div className="quality-stat danger"><span>阻断错误</span><strong>{report.data.summary.errors}</strong></div></div>{!report.data.issues.length ? <Empty text="未发现需要处理的质量问题" /> : <div className="table-scroll"><table><thead><tr><th>级别</th><th>规则</th><th>问题</th><th>来源</th></tr></thead><tbody>{report.data.issues.map((issue, index) => <tr key={`${issue.code}-${index}`}><td><Status value={issue.severity === 'error' ? 'open' : 'review'} /></td><td><code>{issue.code}</code></td><td>{issue.message}</td><td>{issue.source ? `${issue.source.file_name} · ${issue.source.sheet_name} · ${issue.source.start_row} 行` : '项目画像'}</td></tr>)}</tbody></table></div>}</>}</div></section>
}

function Imports() {
  const qc = useQueryClient(), [open, setOpen] = useState(false), [selected, setSelected] = useState<string>()
  const projects = useQuery({ queryKey: ['projects'], queryFn: () => request<Project[]>('/projects') })
  const jobs = useQuery({ queryKey: ['imports'], queryFn: () => request<ImportJob[]>('/imports'), refetchInterval: q => q.state.data?.some(j => ['queued', 'analyzing', 'parsing'].includes(j.status)) ? 1200 : false })
  const selectedJob = jobs.data?.find(job => job.id === selected)
  const issues = useQuery({ queryKey: ['issues', selected], queryFn: () => request<ImportIssue[]>(`/imports/${selected}/issues`), enabled: !!selected })
  const preview = useQuery({ queryKey: ['parse-preview', selected], queryFn: () => request<ImportParsePreview>(`/imports/${selected}/parse-preview`), enabled: selectedJob?.status === 'mapping_review' })
  const resolve = useMutation({ mutationFn: ({ job, issue }: { job: string; issue: string }) => request(`/imports/${job}/issues/${issue}`, { method: 'PATCH', body: JSON.stringify({ status: 'ignored', resolution: '用户确认忽略' }) }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['issues'] }); qc.invalidateQueries({ queryKey: ['imports'] }) } })
  const confirm = useMutation({ mutationFn: (tables: ImportParsePreview['tables']) => request(`/imports/${selected}/confirm-mapping`, { method: 'POST', body: JSON.stringify({ tables, save_profile: true }) }), onSuccess: () => qc.invalidateQueries() })
  const publish = useMutation({ mutationFn: (id: string) => request(`/imports/${id}/publish`, { method: 'POST' }), onSuccess: () => { qc.invalidateQueries(); setSelected(undefined) } })
  return <section className="page"><Title title="项目与导入" text="先上传历史 Excel，系统会识别表头、保留原始文件，再进入异常复核。"><Button className="primary" onClick={() => setOpen(true)}><UploadCloud />上传 Excel</Button></Title><div className="import-guide"><div className="import-guide-main"><div className="import-guide-icon"><FileSpreadsheet /></div><div><h2>从一份造价 Excel 开始</h2><p>支持常见的清单、综合单价分析、工料机、定额和取费表。上传后先预览识别结果，确认映射才会解析入库。</p><div className="file-types"><span><CircleCheck />.xls</span><span><CircleCheck />.xlsx</span><span><CircleCheck />.xlsm</span></div></div></div><Button className="guide-upload" onClick={() => setOpen(true)}><FolderUp />选择文件开始</Button></div><div className="import-steps"><div><b>01</b><span><strong>准备文件</strong><small>保留表头和工作表名称</small></span></div><div><b>02</b><span><strong>上传并预览</strong><small>核对系统识别的字段映射</small></span></div><div><b>03</b><span><strong>复核后发布</strong><small>异常不会静默进入正式数据</small></span></div><div className="import-tip"><Info /><span>建议一次上传同一项目的相关工作表，可多选文件。</span></div></div><ErrorLine error={jobs.error || publish.error || confirm.error} /><div className="split"><div className="panel"><div className="panel-head"><div><h2>导入任务</h2><p>上传后，任务会出现在这里</p></div><Button title="刷新" onClick={() => jobs.refetch()}><RefreshCw /></Button></div>{!jobs.data?.length ? <div className="import-empty"><Database /><strong>还没有导入任务</strong><span>点击上方“上传 Excel”，填写项目基本信息并选择文件。</span><Button className="primary" onClick={() => setOpen(true)}><UploadCloud />上传第一份文件</Button></div> : <div className="task-list">{jobs.data.map(j => <button key={j.id} className={selected === j.id ? 'selected' : ''} onClick={() => setSelected(j.id)}><div><strong>{projects.data?.find(p => p.id === j.project_id)?.name || '项目'}</strong><small>{new Date(j.created_at).toLocaleString()} · {j.processed_files}/{j.total_files} 文件</small></div><div className="progress"><span style={{ width: `${j.progress}%` }} /></div><Status value={j.status} />{j.open_issue_count > 0 && <b>{j.open_issue_count}</b>}</button>)}</div>}</div><div className="panel review"><div className="panel-head"><div><h2>{selectedJob?.status === 'mapping_review' ? '字段映射确认' : '异常复核'}</h2><p>未识别内容不会静默进入正式数据</p></div>{selectedJob?.status === 'review' && <Button className="primary" onClick={() => publish.mutate(selectedJob.id)}><Check />发布版本</Button>}</div>{!selected ? <Empty text="请选择导入任务" /> : selectedJob?.status === 'mapping_review' ? <MappingReview preview={preview.data} pending={confirm.isPending} onConfirm={tables => confirm.mutate(tables)} /> : !issues.data?.length ? <Empty text="该任务没有异常" /> : <div className="issue-list">{issues.data.map(i => <article key={i.id}><div><Status value={i.status} /><code>{i.code}</code></div><strong>{i.message}</strong><small>{i.sheet_name || '工作簿'} {i.cell_range || ''}</small>{i.status === 'open' && <Button onClick={() => resolve.mutate({ job: selected, issue: i.id })}><X />忽略并记录</Button>}</article>)}</div>}</div></div>{open && <ImportDialog close={() => setOpen(false)} done={() => { setOpen(false); qc.invalidateQueries() }} />}</section>
}

function MappingReview({ preview, pending, onConfirm }: { preview?: ImportParsePreview; pending: boolean; onConfirm: (tables: ImportParsePreview['tables']) => void }) {
  if (!preview) return <Empty text="正在读取工作表结构" />
  return <div className="mapping-review">{preview.tables.map((table, index) => <article key={`${table.source_file_id}-${table.sheet_name}`}><div><strong>{table.sheet_name}</strong><small>{table.report_type} · 表头第 {table.header_rows.join('、')} 行</small></div><table><thead><tr><th>系统字段</th><th>原始表头路径</th></tr></thead><tbody>{Object.entries(table.columns).map(([field, detail]) => <tr key={field}><td><code>{field}</code></td><td>{detail.header_path.join(' / ') || `第 ${detail.column} 列`}</td></tr>)}</tbody></table>{index === preview.tables.length - 1 && <Button className="primary" disabled={pending} onClick={() => onConfirm(preview.tables)}><Check />确认映射并解析</Button>}</article>)}</div>
}
function ImportDialog({ close, done }: { close: () => void; done: () => void }) {
  const [files, setFiles] = useState<FileList | null>(null), [error, setError] = useState(''); const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget), body = new FormData(); body.set('metadata_json', JSON.stringify({ name: f.get('name'), region: f.get('region'), pricing_date: f.get('pricing_date'), specialty: f.get('specialty'), pricing_mode: f.get('pricing_mode'), result_stage: f.get('result_stage'), area: f.get('area') || null })); if (files) Array.from(files).forEach(file => body.append('files', file)); try { await request('/imports', { method: 'POST', body }); done() } catch (x) { setError(x instanceof Error ? x.message : '导入失败') } }
  return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><div className="panel-head"><div><h2>导入项目 Excel</h2><p>填写项目基本信息，再选择一个或多个工作簿。</p></div><Button type="button" onClick={close}><X /></Button></div><div className="form-grid"><label className="span-2">项目名称<Input name="name" placeholder="例如：西安高新区住宅项目" required /></label><label>地区<Input name="region" defaultValue="西安" required /></label><label>计价时间<Input name="pricing_date" type="month" required /></label><label>专业<Select name="specialty"><option>土建</option><option>安装</option><option>市政</option><option>装饰</option></Select></label><label>计价体系<Select name="pricing_mode"><option>内地清单定额</option><option>港式清单</option></Select></label><label>成果阶段<Select name="result_stage"><option>结算</option><option>预算</option><option>概算</option></Select></label><label>建筑面积（m²）<Input name="area" /></label><label className="span-2 file-drop"><strong>选择 Excel 文件</strong><Input type="file" multiple accept=".xls,.xlsx,.xlsm,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required onChange={e => setFiles(e.target.files)} /><span>支持 .xls、.xlsx、.xlsm；建议保留原始表头，可多选。</span>{files?.length ? <em>{files.length} 个文件已选择</em> : null}</label></div>{error && <div className="error-line">{error}</div>}<footer><Button type="button" onClick={close}>取消</Button><Button className="primary"><UploadCloud />开始导入</Button></footer></form></div>
}

const libraryLabels: Record<LibraryKey, string> = { catalog: '清单库', resource: '工料机库', quota: '定额库' }
const LIBRARY_PAGE_SIZE = 50
type LibraryColumnKey = 'code' | 'name' | 'description' | 'data_type' | 'unit' | 'quantity' | 'unit_price' | 'total' | 'project' | 'status'
type LibraryColumn = { key: LibraryColumnKey; label: string; locked?: boolean }
const libraryColumns: Record<LibraryKey, LibraryColumn[]> = {
  catalog: [
    { key: 'code', label: '清单编码', locked: true }, { key: 'name', label: '清单名称', locked: true }, { key: 'description', label: '项目特征' },
    { key: 'unit', label: '计量单位' }, { key: 'quantity', label: '工程量' }, { key: 'unit_price', label: '综合单价' }, { key: 'total', label: '合价' }, { key: 'project', label: '项目 / 时间' }, { key: 'status', label: '样本状态' },
  ],
  resource: [
    { key: 'data_type', label: '类型' }, { key: 'name', label: '名称 / 规格', locked: true }, { key: 'unit', label: '单位' }, { key: 'quantity', label: '数量' }, { key: 'unit_price', label: '单价' }, { key: 'project', label: '项目 / 时间' }, { key: 'status', label: '样本状态' },
  ],
  quota: [
    { key: 'data_type', label: '类型' }, { key: 'name', label: '名称 / 规格', locked: true }, { key: 'unit', label: '单位' }, { key: 'quantity', label: '数量' }, { key: 'unit_price', label: '单价' }, { key: 'project', label: '项目 / 时间' }, { key: 'status', label: '样本状态' },
  ],
}
const columnStorageKey = (library: LibraryKey) => `cost-data-columns-${library}`
const defaultVisibleColumns = (library: LibraryKey) => libraryColumns[library].map(column => column.key)
function loadVisibleColumns(library: LibraryKey): LibraryColumnKey[] {
  const defaults = defaultVisibleColumns(library)
  if (typeof localStorage === 'undefined') return defaults
  try {
    const stored = JSON.parse(localStorage.getItem(columnStorageKey(library)) || 'null')
    if (!Array.isArray(stored)) return defaults
    const allowed = new Set(defaults)
    const selected = stored.filter((key): key is LibraryColumnKey => typeof key === 'string' && allowed.has(key as LibraryColumnKey))
    return libraryColumns[library].filter(column => column.locked).map(column => column.key).concat(selected.filter(key => !libraryColumns[library].find(column => column.key === key)?.locked)).filter((key, index, all) => all.indexOf(key) === index)
  } catch { return defaults }
}

function Explorer({ go }: { go: (library: LibraryKey) => void }) {
  const [query, setQuery] = useState(''), [dataType, setDataType] = useState('all'), [unit, setUnit] = useState(''), [region, setRegion] = useState(''), [active, setActive] = useState(''); const result = useQuery({ queryKey: ['workspace', query, dataType, unit, region], queryFn: () => request<WorkspaceSearchResult>(`/workspace/search?query=${encodeURIComponent(query)}&data_type=${dataType}&unit=${encodeURIComponent(unit)}&region=${encodeURIComponent(region)}&limit=100`) }); const current = result.data?.items.find(item => item.id === active);
  return <section className="page"><Title title="造价数据工作台（跨库总览）" text="独立 Tab：统一检索清单库、工料机库和定额库。" /><WorkspaceFilters query={query} setQuery={setQuery} dataType={dataType} setDataType={setDataType} region={region} setRegion={setRegion} unit={unit} setUnit={setUnit} total={result.data?.total || 0} /><ErrorLine error={result.error} /><div className="explorer-grid"><div className="panel table-panel"><LibraryTable items={result.data?.items || []} active={active} select={setActive} onLibrary={go} showLibrary /></div><WorkspaceEvidence item={current} /></div></section>
}

function WorkspaceFilters({ query, setQuery, dataType, setDataType, region, setRegion, unit, setUnit, total, showDataType = true }: { query: string; setQuery: (value: string) => void; dataType: string; setDataType: (value: string) => void; region: string; setRegion: (value: string) => void; unit: string; setUnit: (value: string) => void; total: number; showDataType?: boolean }) {
  return <div className={`workspace-filters ${showDataType ? '' : 'library-filters'}`}><div className="searchbar"><Search /><Input value={query} onChange={event => setQuery(event.target.value)} placeholder="名称、编码、规格或项目特征" /><span className="result-count" aria-label={`共 ${total} 条记录`}>{total.toLocaleString()} 条</span></div>{showDataType && <Select value={dataType} onChange={event => setDataType(event.target.value)}><option value="all">全部数据</option><option value="bill">清单</option><option value="quota">定额</option><option value="resource">工料机</option></Select>}<Input value={region} onChange={event => setRegion(event.target.value)} placeholder="地区" /><Input value={unit} onChange={event => setUnit(event.target.value)} placeholder="单位" /></div>
}

type ReferenceFilters = { query: string; region: string; specialty: string; dateFrom: string; dateTo: string; referenceScope: 'available' | 'restricted' | 'all'; projectType: string; pricingMode: string; resultStage: string; unit: string; priceMin: string; priceMax: string; taxInclusion: string; priceType: string; priceSourceStatus: string; sortBy: 'reference' | 'unit_price' | 'quantity' | 'pricing_date' }
const defaultReferenceFilters: ReferenceFilters = { query: '', region: '', specialty: '', dateFrom: '', dateTo: '', referenceScope: 'available', projectType: '', pricingMode: '', resultStage: '', unit: '', priceMin: '', priceMax: '', taxInclusion: '', priceType: '', priceSourceStatus: '', sortBy: 'reference' }

function CatalogReferenceFilters({ filters, setFilters, result, reset }: { filters: ReferenceFilters; setFilters: (next: ReferenceFilters) => void; result?: WorkspaceSearchResult; reset: () => void }) {
  const [advanced, setAdvanced] = useState(false)
  const update = (key: keyof ReferenceFilters, value: string) => setFilters({ ...filters, [key]: value } as ReferenceFilters)
  const active = ([['region', '地区'], ['specialty', '专业'], ['dateFrom', '起始时间'], ['dateTo', '截止时间'], ['projectType', '项目类型'], ['pricingMode', '计价体系'], ['resultStage', '成果阶段'], ['unit', '单位'], ['priceMin', '最低单价'], ['priceMax', '最高单价'], ['taxInclusion', '含税方式'], ['priceType', '价格类型'], ['priceSourceStatus', '价格口径']] as const).filter(([key]) => Boolean(filters[key]))
  const applyPreset = (preset: 'recentSettlement' | 'sameSpecialty' | 'taxIncluded') => {
    const currentYear = new Date().getFullYear()
    if (preset === 'recentSettlement') setFilters({ ...filters, dateFrom: `${currentYear - 3}-01`, resultStage: '结算', referenceScope: 'available' })
    if (preset === 'sameSpecialty') setFilters({ ...filters, referenceScope: 'available' })
    if (preset === 'taxIncluded') setFilters({ ...filters, taxInclusion: '含税', priceType: '综合单价', referenceScope: 'available' })
  }
  const savePreset = () => localStorage.setItem('cost-data-catalog-reference-filter', JSON.stringify(filters))
  const restorePreset = () => { try { const saved = localStorage.getItem('cost-data-catalog-reference-filter'); if (saved) setFilters({ ...defaultReferenceFilters, ...JSON.parse(saved) }) } catch { /* Ignore malformed local preferences. */ } }
  return <div className="reference-filters"><div className="reference-filter-row"><div className="reference-search"><Search /><Input aria-label="检索清单" value={filters.query} onChange={event => update('query', event.target.value)} placeholder="名称、编码、规格或项目特征" /><span>{result?.total.toLocaleString() || 0} 条</span></div><Select aria-label="地区" value={filters.region} onChange={event => update('region', event.target.value)}><option value="">全部地区</option><option value="西安">西安</option><option value="北京">北京</option><option value="上海">上海</option></Select><Select aria-label="专业" value={filters.specialty} onChange={event => update('specialty', event.target.value)}><option value="">全部专业</option><option value="土建">土建</option><option value="安装">安装</option><option value="市政">市政</option><option value="装饰">装饰</option></Select><label className="date-filter"><span>计价时间</span><Input aria-label="计价起始时间" type="month" value={filters.dateFrom} onChange={event => update('dateFrom', event.target.value)} /><b>至</b><Input aria-label="计价截止时间" type="month" value={filters.dateTo} onChange={event => update('dateTo', event.target.value)} /></label><Select aria-label="样本状态" value={filters.referenceScope} onChange={event => update('referenceScope', event.target.value)}><option value="available">仅可参考样本</option><option value="all">全部样本</option><option value="restricted">仅受限样本</option></Select><Button type="button" aria-expanded={advanced} onClick={() => setAdvanced(!advanced)}><SlidersHorizontal />高级筛选</Button></div><div className="reference-summary"><span><CircleCheck />可参考 {result?.available_count || 0}</span><span className="restricted-count"><CircleAlert />受限 {result?.restricted_count || 0}</span><Select aria-label="排序方式" value={filters.sortBy} onChange={event => update('sortBy', event.target.value)}><option value="reference">可用性 · 最近时间</option><option value="unit_price">综合单价从高到低</option><option value="quantity">工程量从高到低</option><option value="pricing_date">计价时间从近到远</option></Select></div>{(active.length > 0 || filters.referenceScope !== 'all') && <div className="filter-chips" aria-label="当前筛选条件">{filters.referenceScope === 'available' && <span>仅可参考样本<button aria-label="显示全部样本" onClick={() => update('referenceScope', 'all')}><X /></button></span>}{active.map(([key, label]) => <span key={key}>{label}：{filters[key]}<button aria-label={`清除${label}`} onClick={() => update(key, '')}><X /></button></span>)}<button className="clear-filters" onClick={reset}>清除全部</button></div>}<div className="reference-presets"><span>常用组合</span><button onClick={() => applyPreset('recentSettlement')}>本地区近三年结算价</button><button onClick={() => applyPreset('sameSpecialty')}>同专业可用样本</button><button onClick={() => applyPreset('taxIncluded')}>含税综合单价</button><i /><button onClick={savePreset}>保存常用筛选</button><button onClick={restorePreset}>读取已保存</button></div>{advanced && <div className="advanced-filters"><label>项目类型<Select value={filters.projectType} onChange={event => update('projectType', event.target.value)}><option value="">不限</option><option value="住宅">住宅</option><option value="商业">商业</option><option value="公共建筑">公共建筑</option></Select></label><label>计价体系<Select value={filters.pricingMode} onChange={event => update('pricingMode', event.target.value)}><option value="">不限</option><option value="内地清单定额">内地清单定额</option><option value="港式清单">港式清单</option></Select></label><label>成果阶段<Select value={filters.resultStage} onChange={event => update('resultStage', event.target.value)}><option value="">不限</option><option value="结算">结算</option><option value="预算">预算</option><option value="概算">概算</option></Select></label><label>计量单位<Input value={filters.unit} onChange={event => update('unit', event.target.value)} placeholder="例如 m3" /></label><label>综合单价（元）<span className="range-inputs"><Input inputMode="decimal" value={filters.priceMin} onChange={event => update('priceMin', event.target.value)} placeholder="最低" /><b>—</b><Input inputMode="decimal" value={filters.priceMax} onChange={event => update('priceMax', event.target.value)} placeholder="最高" /></span></label><label>含税方式<Select value={filters.taxInclusion} onChange={event => update('taxInclusion', event.target.value)}><option value="">不限</option><option value="含税">含税</option><option value="不含税">不含税</option></Select></label><label>价格类型<Select value={filters.priceType} onChange={event => update('priceType', event.target.value)}><option value="">不限</option><option value="综合单价">综合单价</option><option value="结算价">结算价</option><option value="预算价">预算价</option></Select></label><label>价格来源<Select value={filters.priceSourceStatus} onChange={event => update('priceSourceStatus', event.target.value)}><option value="">不限</option><option value="complete">口径完整</option><option value="incomplete">口径待确认</option></Select></label></div>}</div>
}

function LibraryExplorer({ library, ready }: { library: LibraryKey; ready: boolean }) {
  const qc = useQueryClient(), [query, setQuery] = useState(''), [unit, setUnit] = useState(''), [region, setRegion] = useState(''), [referenceFilters, setReferenceFilters] = useState<ReferenceFilters>(defaultReferenceFilters), [active, setActive] = useState(''), [page, setPage] = useState(1), [editing, setEditing] = useState<WorkspaceRecord>(), [visibleColumns, setVisibleColumns] = useState<LibraryColumnKey[]>(() => loadVisibleColumns(library)), [evidenceWidth, setEvidenceWidth] = useState(() => { const value = typeof localStorage === 'undefined' ? 378 : Number(localStorage.getItem('cost-data-evidence-width')); return Number.isFinite(value) && value >= 300 && value <= 560 ? value : 378 }), [resizingEvidence, setResizingEvidence] = useState(false)
  const libraries = useQuery({ queryKey: ['libraries'], queryFn: () => request<LibrarySummary[]>('/libraries'), enabled: ready })
  const libraryQuery = useMemo(() => { const values = library === 'catalog' ? { query: referenceFilters.query, unit: referenceFilters.unit, region: referenceFilters.region, specialty: referenceFilters.specialty, pricing_date_from: referenceFilters.dateFrom, pricing_date_to: referenceFilters.dateTo, reference_scope: referenceFilters.referenceScope, project_type: referenceFilters.projectType, pricing_mode: referenceFilters.pricingMode, result_stage: referenceFilters.resultStage, price_min: referenceFilters.priceMin, price_max: referenceFilters.priceMax, tax_inclusion: referenceFilters.taxInclusion, price_type: referenceFilters.priceType, price_source_status: referenceFilters.priceSourceStatus, sort_by: referenceFilters.sortBy } : { query, unit, region }; const params = new URLSearchParams({ offset: String((page - 1) * LIBRARY_PAGE_SIZE), limit: String(LIBRARY_PAGE_SIZE) }); Object.entries(values).forEach(([key, value]) => { if (value) params.set(key, value) }); return params.toString() }, [library, page, query, unit, region, referenceFilters])
  const result = useQuery({ queryKey: ['library', library, libraryQuery], queryFn: () => request<WorkspaceSearchResult>(`/libraries/${library}/search?${libraryQuery}`), enabled: ready })
  const current = result.data?.items.find(item => item.id === active)
  const summary = libraries.data?.find(item => item.key === library)
  const resetPage = (update: (value: string) => void) => (value: string) => { update(value); setPage(1); setActive('') }
  const updateReferenceFilters = (next: ReferenceFilters) => { setReferenceFilters(next); setPage(1); setActive('') }
  const clearReferenceFilters = () => updateReferenceFilters(defaultReferenceFilters)
  useEffect(() => { if (!resizingEvidence) return; const move = (event: PointerEvent) => { const next = Math.min(560, Math.max(300, window.innerWidth - event.clientX)); setEvidenceWidth(next) }; const stop = () => setResizingEvidence(false); window.addEventListener('pointermove', move); window.addEventListener('pointerup', stop); return () => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', stop) } }, [resizingEvidence])
  const beginResizeEvidence = () => { setResizingEvidence(true); document.body.style.cursor = 'col-resize'; document.body.style.userSelect = 'none' }
  useEffect(() => { if (!resizingEvidence) { document.body.style.cursor = ''; document.body.style.userSelect = ''; if (typeof localStorage !== 'undefined') localStorage.setItem('cost-data-evidence-width', String(evidenceWidth)) } }, [resizingEvidence, evidenceWidth])
  const saveEvidenceWidth = () => { if (typeof localStorage !== 'undefined') localStorage.setItem('cost-data-evidence-width', String(evidenceWidth)) }
  const updateColumns = (next: LibraryColumnKey[]) => { setVisibleColumns(next); if (typeof localStorage !== 'undefined') localStorage.setItem(columnStorageKey(library), JSON.stringify(next)) }
  return <section className="page library-page"><div className="library-toolbar"><Title title={libraryLabels[library]} text={`${summary?.record_count || 0} 条已发布记录 · ${summary?.project_count || 0} 个项目`} /><div className="library-tools">{library === 'catalog' ? <CatalogReferenceFilters filters={referenceFilters} setFilters={updateReferenceFilters} result={result.data} reset={clearReferenceFilters} /> : <WorkspaceFilters query={query} setQuery={resetPage(setQuery)} dataType="all" setDataType={() => undefined} region={region} setRegion={resetPage(setRegion)} unit={unit} setUnit={resetPage(setUnit)} total={result.data?.total || 0} showDataType={false} />}<ColumnSettings library={library} visibleColumns={visibleColumns} onChange={updateColumns} /></div><ErrorLine error={libraries.error || result.error} /></div><div className={`explorer-grid ${current ? 'has-evidence' : ''}`} style={current ? { gridTemplateColumns: `minmax(0, 1fr) ${evidenceWidth}px` } : undefined}><div className="panel table-panel"><LibraryTable items={result.data?.items || []} active={active} select={setActive} standardBillColumns={library === 'catalog'} columns={visibleColumns} emptyText={library === 'catalog' ? '没有找到可参考样本。可尝试显示受限样本、放宽时间或地区条件。' : undefined} /><LibraryPagination total={result.data?.total || 0} page={page} setPage={nextPage => { setPage(nextPage); setActive('') }} /></div>{current && <div className="evidence-shell"><div className="evidence-resize-handle" role="separator" aria-label="调整证据栏宽度" onPointerDown={beginResizeEvidence} onDoubleClick={() => { setEvidenceWidth(378); localStorage.setItem('cost-data-evidence-width', '378') }} /><WorkspaceEvidence item={current} editable={library === 'catalog'} onEdit={() => current && setEditing(current)} onClose={() => { saveEvidenceWidth(); setActive('') }} /></div>}</div>{editing && <BillEditDialog item={editing} close={() => setEditing(undefined)} done={() => { setEditing(undefined); qc.invalidateQueries({ queryKey: ['library', library] }) }} />}</section>
}

function ColumnSettings({ library, visibleColumns, onChange }: { library: LibraryKey; visibleColumns: LibraryColumnKey[]; onChange: (columns: LibraryColumnKey[]) => void }) {
  const [open, setOpen] = useState(false)
  const columns = libraryColumns[library]
  const toggle = (key: LibraryColumnKey) => { if (columns.find(column => column.key === key)?.locked) return; const next = visibleColumns.includes(key) ? visibleColumns.filter(column => column !== key) : [...visibleColumns, key]; if (next.length) onChange(next) }
  return <div className="column-settings"><Button aria-expanded={open} onClick={() => setOpen(!open)}><SlidersHorizontal />列设置</Button>{open && <div className="column-settings-popover"><div className="column-settings-head"><strong>显示列</strong><span>选择需要展示的字段</span></div>{columns.map(column => <label key={column.key}><Input type="checkbox" checked={visibleColumns.includes(column.key)} disabled={column.locked} onChange={() => toggle(column.key)} /><span>{column.label}</span>{column.locked && <small>核心</small>}</label>)}<Button onClick={() => onChange(defaultVisibleColumns(library))}>恢复默认</Button></div>}</div>
}

function LibraryPagination({ total, page, setPage }: { total: number; page: number; setPage: (page: number) => void }) {
  const pages = Math.max(1, Math.ceil(total / LIBRARY_PAGE_SIZE)), start = total ? (page - 1) * LIBRARY_PAGE_SIZE + 1 : 0, end = Math.min(page * LIBRARY_PAGE_SIZE, total)
  return <footer className="library-pagination" aria-label="清单分页"><span>显示 {start}–{end}，共 {total} 条</span><div><Button disabled={page === 1} onClick={() => setPage(page - 1)}>上一页</Button><strong>第 {page} / {pages} 页</strong><Button disabled={page === pages} onClick={() => setPage(page + 1)}>下一页</Button></div></footer>
}

function LibraryTable({ items, active, select, onLibrary, showLibrary = false, standardBillColumns = false, columns, emptyText }: { items: WorkspaceRecord[]; active: string; select: (id: string) => void; onLibrary?: (library: LibraryKey) => void; showLibrary?: boolean; standardBillColumns?: boolean; columns?: LibraryColumnKey[]; emptyText?: string }) {
  if (!items.length) return <Empty text={emptyText || '没有符合条件的数据'} />
  const visible = columns || (standardBillColumns ? defaultVisibleColumns('catalog') : defaultVisibleColumns('resource'))
  const has = (key: LibraryColumnKey) => visible.includes(key)
  if (standardBillColumns) return <div className="table-scroll"><table className="bill-table"><thead><tr>{has('code') && <th className="column-code">清单编码</th>}{has('name') && <th className="column-name">清单名称</th>}{has('description') && <th className="column-description">项目特征</th>}{has('unit') && <th className="column-unit">计量单位</th>}{has('quantity') && <th className="column-quantity">工程量</th>}{has('unit_price') && <th className="column-unit_price">综合单价</th>}{has('total') && <th className="column-total">合价</th>}{has('project') && <th className="column-project">项目 / 时间</th>}{has('status') && <th className="column-status">样本状态</th>}</tr></thead><tbody>{items.map(item => <tr key={`bill-${item.id}`} className={active === item.id ? 'selected' : ''} onClick={() => select(item.id)}>{has('code') && <td className="column-code">{item.code || '—'}</td>}{has('name') && <td className="column-name"><strong>{item.name}</strong>{item.specification && <small>{item.specification}</small>}</td>}{has('description') && <td className="column-description feature-cell"><div className="feature-summary">{formatProjectFeature(item.description)}</div></td>}{has('unit') && <td className="column-unit">{item.unit || '—'}</td>}{has('quantity') && <td className="column-quantity num">{formatAmount(item.quantity)}</td>}{has('unit_price') && <td className="column-unit_price num">{formatAmount(item.unit_price)}</td>}{has('total') && <td className="column-total num">{formatAmount(item.total)}</td>}{has('project') && <td className="column-project">{item.project_name}<small>{item.region} · {item.pricing_date}</small></td>}{has('status') && <td className="column-status"><Status value={item.comparability} /></td>}</tr>)}</tbody></table></div>
  return <div className="table-scroll"><table><thead><tr>{showLibrary && <th>所属库</th>}{has('data_type') && <th>类型</th>}{has('name') && <th>名称 / 规格</th>}{has('unit') && <th>单位</th>}{has('quantity') && <th>数量</th>}{has('unit_price') && <th>单价</th>}{has('project') && <th>项目 / 时间</th>}{has('status') && <th>样本状态</th>}</tr></thead><tbody>{items.map(item => <tr key={`${item.library || item.data_type}-${item.id}`} className={active === item.id ? 'selected' : ''} onClick={() => select(item.id)}>{showLibrary && <td><button className="library-link" onClick={event => { event.stopPropagation(); if (item.library) onLibrary?.(item.library) }}>{item.library ? libraryLabels[item.library] : '中心库'}</button></td>}{has('data_type') && <td><Status value={item.data_type} /></td>}{has('name') && <td><strong>{item.name}</strong><small>{item.code || item.specification || '—'}</small></td>}{has('unit') && <td>{item.unit || '—'}</td>}{has('quantity') && <td className="num">{formatAmount(item.quantity)}</td>}{has('unit_price') && <td className="num">{formatAmount(item.unit_price)}</td>}{has('project') && <td>{item.project_name}<small>{item.region} · {item.pricing_date}</small></td>}{has('status') && <td><Status value={item.comparability} /></td>}</tr>)}</tbody></table></div>
}
function WorkspaceEvidence({ item, editable = false, onEdit, onClose }: { item?: WorkspaceRecord; editable?: boolean; onEdit?: () => void; onClose?: () => void }) {
  const panelHead = <div className="panel-head"><div><h2>证据与口径</h2><p>原始值、标准口径和来源分开呈现</p></div><div className="evidence-actions">{editable && item && <Button onClick={onEdit}><Pencil />编辑清单</Button>}{item && <Button className="icon-button" title="关闭证据面板" aria-label="关闭证据面板" onClick={onClose}><X /></Button>}</div></div>
  if (!item) return <aside className="evidence">{panelHead}<Empty text="选择一条记录查看来源" /></aside>
  const attributes = item.attributes || {}, value = (key: string) => attributes[key] === undefined || attributes[key] === null || attributes[key] === '' ? '—' : typeof attributes[key] === 'string' ? attributes[key] : JSON.stringify(attributes[key])
  const priceContext = item.price_context || {}, hasCompletePrice = !!(priceContext.tax_inclusion && priceContext.price_type && priceContext.price_source)
  const sourceName = item.source?.file_name || value('source')
  const Disclosure = ({ title, children }: { title: string; children: React.ReactNode }) => <details className="evidence-disclosure" open><summary><strong>{title}</strong><ChevronDown /></summary>{children}</details>
  return <aside className="evidence">{panelHead}<div className="evidence-body evidence-reference"><section className="evidence-card price-availability"><h3>价格可用性</h3><div className={`price-alert ${hasCompletePrice ? 'ready' : ''}`}><CircleAlert /><div><strong>{hasCompletePrice ? '价格口径完整' : '价格待确认'}</strong><span>{hasCompletePrice ? '价格来源与口径已完整记录，可用于参考。' : '缺少价格来源数据，仅展示原始值'}</span></div></div><div className="price-metrics"><div><span>价格类型</span><b>{priceContext.price_type || '综合单价'}</b></div><div><span>含税方式</span><b>{priceContext.tax_inclusion || '不含税'}</b></div><div><span>来源状态</span><b>{priceContext.price_source || '待确认'}</b></div><div><span>口径一致性</span><b>{hasCompletePrice ? '一致' : '—'}</b></div></div></section><section className="evidence-card availability-conclusion"><h3>可用性结论</h3><p>{hasCompletePrice ? '当前条目价格口径完整，可作为同类清单的参考样本。' : '当前条目缺少有效价格数据，暂不建议采用。'}</p><p className="suggestion">建议：{hasCompletePrice ? '结合项目时间、地区与适用范围进行比对。' : '补充价格来源或参考同类项目口径后再评估。'}</p>{!hasCompletePrice && editable && <Button onClick={onEdit}>补充价格来源</Button>}</section><section className="evidence-card source-trace"><h3>来源追溯</h3><dl><dt>文件</dt><dd>{sourceName}</dd><dt>工作表</dt><dd>{item.source?.sheet_name || '—'}</dd><dt>行号</dt><dd>第 {item.source?.start_row || '—'} 行</dd><dt>更新时间</dt><dd>—</dd><dt>来源项目</dt><dd>{item.project_name} · {item.region} · {item.pricing_date}</dd></dl></section><Disclosure title="关联定额编码"><p>{value('related_quota_codes')}</p></Disclosure><Disclosure title="适用范围"><p>专业：{value('specialty')}</p><p>适用范围：{value('applicable_scope')}</p></Disclosure><Disclosure title="结构分组"><p>{value('structure_group')}</p></Disclosure><Disclosure title="备注"><p>{value('remark')}</p></Disclosure></div></aside>
}

function BillEditDialog({ item, close, done }: { item: WorkspaceRecord; close: () => void; done: () => void }) {
  const save = useMutation({ mutationFn: (body: Record<string, string | null>) => request<WorkspaceRecord>(`/libraries/catalog/records/${item.id}`, { method: 'PATCH', body: JSON.stringify(body) }), onSuccess: done })
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); const value = (key: string) => String(form.get(key) || '').trim() || null; save.mutate({ code: value('code'), name: value('name'), specification: value('specification'), description: value('description'), unit: value('unit'), quantity: value('quantity'), unit_price: value('unit_price'), total: value('total') }) }
  return <div className="modal-backdrop"><form className="modal bill-edit-modal" onSubmit={submit}><div className="panel-head"><div><h2>编辑清单</h2><p>保存后将同步更新清单库；原始文件证据保持不变。</p></div><Button type="button" onClick={close}><X /></Button></div><div className="form-grid"><label>清单编码<Input name="code" defaultValue={item.code || ''} /></label><label>计量单位<Input name="unit" defaultValue={item.unit || ''} /></label><label className="span-2">清单名称<Input name="name" required defaultValue={item.name} /></label><label className="span-2">规格型号<Input name="specification" defaultValue={item.specification || ''} /></label><label className="span-2">项目特征<Textarea name="description" defaultValue={item.description || ''} /></label><label>工程量<Input name="quantity" inputMode="decimal" defaultValue={item.quantity.value || ''} /></label><label>综合单价<Input name="unit_price" inputMode="decimal" defaultValue={item.unit_price.value || ''} /></label><label>合价<Input name="total" inputMode="decimal" defaultValue={item.total.value || ''} /></label></div><ErrorLine error={save.error} /><footer><Button type="button" onClick={close}>取消</Button><Button className="primary" disabled={save.isPending}><Check />{save.isPending ? '保存中' : '保存修改'}</Button></footer></form></div>
}

function Matching() {
  const [name, setName] = useState(''), [unit, setUnit] = useState('m3'), [saved, setSaved] = useState(''); const create = useMutation({ mutationFn: () => request<any>('/match-sessions', { method: 'POST', body: JSON.stringify({ name: `匹配 ${new Date().toLocaleDateString()}`, items: [{ name, unit }] }) }) }); const decide = useMutation({ mutationFn: (id: string) => request(`/match-sessions/${create.data.id}/decisions`, { method: 'POST', body: JSON.stringify({ query_index: 0, candidate_cost_item_id: id, decision: 'accepted', remember_rule: true }) }), onSuccess: (_d, id) => setSaved(id) })
  return <section className="page"><Title title="新清单匹配" text="确定性召回和评分，显示评分组成与排除原因。" /><div className="panel match-work"><div className="match-input"><label>待匹配清单名称<Input value={name} onChange={e => setName(e.target.value)} placeholder="例如：现浇混凝土矩形柱 C30" /></label><label>单位<Input value={unit} onChange={e => setUnit(e.target.value)} /></label><Button className="primary" disabled={!name || create.isPending} onClick={() => { setSaved(''); create.mutate() }}>{create.isPending ? <LoaderCircle className="spin" /> : <Search />}查找候选</Button></div><ErrorLine error={create.error || decide.error} />{!create.data ? <Empty text="输入清单项以生成候选" /> : <div className="candidate-list">{create.data.results?.[0]?.candidates?.map((c: any, i: number) => <article key={c.cost_item.id}><div className="rank">{i + 1}</div><div><strong>{c.cost_item.name}</strong><small>{c.cost_item.project_name} · {c.cost_item.region} · {c.cost_item.pricing_date}</small><div className="score-parts">{c.score_parts.map((p: any) => <span key={p.label}>{p.label} {p.score}</span>)}</div></div><div className="candidate-price"><b>¥ {formatAmount(c.cost_item.unit_price)}</b><span>{c.total_score} 分</span></div><Button disabled={!!saved} onClick={() => decide.mutate(c.cost_item.id)}><Check />{saved === c.cost_item.id ? '已确认' : '确认并记住'}</Button></article>)}</div>}</div></section>
}

function Rules() {
  const qc = useQueryClient(), rules = useQuery({ queryKey: ['rules'], queryFn: () => request<Rule[]>('/normalization-rules') }), conversions = useQuery({ queryKey: ['conversions'], queryFn: () => request<UnitConversion[]>('/unit-conversions') }), templates = useQuery({ queryKey: ['templates'], queryFn: () => request<MetricTemplate[]>('/metric-templates') }); const toggle = useMutation({ mutationFn: (r: Rule) => request(`/normalization-rules/${r.id}`, { method: 'PATCH', body: JSON.stringify({ enabled: !r.enabled }) }), onSuccess: () => qc.invalidateQueries({ queryKey: ['rules'] }) }); const createConversion = useMutation({ mutationFn: (body: Record<string, string>) => request('/unit-conversions', { method: 'POST', body: JSON.stringify(body) }), onSuccess: () => qc.invalidateQueries({ queryKey: ['conversions'] }) }); const createTemplate = useMutation({ mutationFn: (body: Record<string, string>) => request('/metric-templates', { method: 'POST', body: JSON.stringify(body) }), onSuccess: () => qc.invalidateQueries({ queryKey: ['templates'] }) });
  return <section className="page"><Title title="标准化与主数据" text="原始值不被覆盖；标准名称、单位换算和指标模板均可追溯。" /><div className="settings-grid"><div className="panel"><div className="panel-head"><h2>名称与分类规则</h2></div>{!rules.data?.length ? <Empty text="尚未建立个人规则" /> : <div className="table-scroll"><table><thead><tr><th>类型</th><th>原始值</th><th>标准值</th><th>启用</th></tr></thead><tbody>{rules.data.map(r => <tr key={r.id}><td>{r.rule_type}</td><td>{r.source_value}</td><td>{r.target_value}</td><td><Input type="checkbox" checked={r.enabled} onChange={() => toggle.mutate(r)} /></td></tr>)}</tbody></table></div>}</div><div className="panel"><div className="panel-head"><h2>单位换算</h2></div><form className="settings-form" onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); createConversion.mutate(Object.fromEntries(['source_unit', 'target_unit', 'factor', 'basis'].map(key => [key, String(form.get(key))]))) }}><label>原始单位<Input name="source_unit" placeholder="t" required /></label><label>标准单位<Input name="target_unit" placeholder="kg" required /></label><label>换算系数<Input name="factor" placeholder="1000" required /></label><label>换算依据<Input name="basis" placeholder="计量换算规则" required /></label><Button className="primary"><Plus />新增换算</Button></form><div className="compact-list">{conversions.data?.map(rule => <div key={rule.id}><span>{rule.source_unit} → {rule.target_unit} × {rule.factor}</span><small>{rule.basis}</small></div>)}</div></div><div className="panel"><div className="panel-head"><h2>指标模板</h2></div><form className="settings-form" onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); createTemplate.mutate(Object.fromEntries(['code', 'name', 'unit', 'formula', 'description'].map(key => [key, String(form.get(key) || '')]))) }}><label>指标编码<Input name="code" required /></label><label>指标名称<Input name="name" required /></label><label>单位<Input name="unit" required /></label><label>计算口径<Input name="formula" required /></label><Button className="primary"><Plus />新增模板</Button></form><div className="compact-list">{templates.data?.map(template => <div key={template.id}><span>{template.name} · {template.unit}</span><small>{template.formula}</small></div>)}</div></div></div></section>
}

function SystemSettings() {
  const qc = useQueryClient(), backups = useQuery({ queryKey: ['backups'], queryFn: () => request<Backup[]>('/backups') }), ai = useQuery({ queryKey: ['ai'], queryFn: () => request<any>('/settings/ai') }), backup = useMutation({ mutationFn: (dir: string) => request('/backups', { method: 'POST', body: JSON.stringify({ target_directory: dir, kind: 'manual' }) }), onSuccess: () => qc.invalidateQueries({ queryKey: ['backups'] }) }); const submitBackup = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); backup.mutate(String(new FormData(e.currentTarget).get('directory'))) }; const submitAI = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); await request('/settings/ai', { method: 'PUT', body: JSON.stringify({ base_url: f.get('base_url'), model: f.get('model'), api_key: f.get('api_key') || null }) }); qc.invalidateQueries({ queryKey: ['ai'] }) }
  return <section className="page"><Title title="备份与 AI" text="备份包含数据库和原始文件；密钥仅存 macOS Keychain。" /><div className="settings-grid"><div className="panel"><div className="panel-head"><h2>本地备份</h2></div><form className="settings-form" onSubmit={submitBackup}><label>备份目录<Input name="directory" placeholder="/Volumes/Backup/cost-data" required /></label><Button className="primary"><Archive />立即备份</Button></form><ErrorLine error={backup.error} /><div className="backup-list">{backups.data?.map(b => <div key={b.id}><div><strong>{new Date(b.created_at).toLocaleString()}</strong><small>{b.path}</small></div><Status value={b.status} /></div>)}</div></div><div className="panel"><div className="panel-head"><div><h2>DeepSeek</h2><p>关闭时不影响核心功能</p></div><Bot /></div>{ai.data && <form className="settings-form" onSubmit={submitAI}><label>API 地址<Input name="base_url" defaultValue={ai.data.base_url} /></label><label>模型<Input name="model" defaultValue={ai.data.model} /></label><label>API Key<Input name="api_key" type="password" placeholder={ai.data.has_api_key ? '已存入 Keychain' : '尚未配置'} /></label><Button className="primary">保存 AI 设置</Button></form>}</div></div></section>
}

export default App
